32	/// Physics module demo. 10 balls bounce inside a closed boundary under gravity. The
33	/// floor adds extra upward speed on contact so balls keep oscillating (the demo
34	/// is self-sustaining, not damped). 7 red balls collide with walls AND each other;
35	/// 3 blue balls only collide with walls (layer-isolated from reds; blue↔blue is
36	/// filtered in the bounce system).
37	public class PhysicsDemoScreen : IGameScreen
38	{
39	    private const float BoundaryHalfWidth  = 380f;
40	    private const float BoundaryHalfHeight = 220f;
41	    private const float WallThickness      = 20f;
42	
43	    private const float Gravity      = 1200f;    // px/s²
44	    private const float Restitution  = 0.85f;    // wall/ball bounce energy retention
45	    private const float FloorBoost   = 260f;     // extra upward px/s on floor contact
46	    private const float MaxFallSpeed = 1400f;    // safety cap to prevent tunneling
47	
48	    private const int RedBallLayer  = 0;
49	    private const int BlueBallLayer = 1;
50	    // Walls own both layers so red and blue both collide with them.
51	
52	    /// 10 balls: 7 red (Type=Red) collide with walls + reds; 3 blue (Type=Blue)
53	    /// collide with walls only. Sizes mostly small with a couple of larger reds
54	    /// for visual variety.
55	    private static readonly BallSpec[] BallSpecs =
56	    {
