64	        new(BallType.Blue,  radius: 13f, spawn: new Vector2( -80,  -80), velocity: new Vector2( -90,   0)),
65	        new(BallType.Blue,  radius: 20f, spawn: new Vector2(  80,  -80), velocity: new Vector2( 110,   0)),
66	        new(BallType.Blue,  radius: 15f, spawn: new Vector2(   0,    0), velocity: new Vector2( 160,   0)),
