159	    public void Reset()
160	    {
161	        for (var i = 0; i < _balls.Count && i < BallSpecs.Length; i++)
162	        {
163	            var ball = _balls[i];
164	            if (!ball.IsAlive) continue;
165	
166	            ref var transform = ref ball.Get<TransformComponent>();
167	            transform.Position = BallSpecs[i].Spawn;
168	            transform.LastPosition = BallSpecs[i].Spawn;
169	
170	            ref var velocity = ref ball.Get<VelocityComponent>();
171	            velocity.Current = BallSpecs[i].Velocity;
172	            velocity.Last = BallSpecs[i].Velocity;
173	        }
174	    }
