197	    private void CreateBoundary()
198	    {
199	        var bounds = new Rectangle(
200	            -(int)BoundaryHalfWidth, -(int)BoundaryHalfHeight,
201	            (int)BoundaryHalfWidth * 2, (int)BoundaryHalfHeight * 2);
202	
203	        var boundary = _world.CreateEntity();
204	        boundary.Set(new TransformComponent(Vector2.Zero));
205	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.2f };
206	        draw.SetMeshData(new RectangleOutlineMeshGenerator(bounds, thickness: 2f, color: SproutPalette.TextLight));
207	        boundary.Set(draw);
208	        boundary.Set<VisibleComponent>();
209	    }
