211	    /// Four BoxColliders forming a closed box just outside the visible boundary.
212	    /// Walls share both red and blue layers so both ball categories collide with
213	    /// them. Walls have zero TransformComponent.Delta so even though they're
214	    /// active colliders, the swept test self-skips when they iterate as entity A.
215	    private void CreateWalls()
216	    {
217	        var redAndBlue = new HashSet<int> { RedBallLayer, BlueBallLayer };
218	
219	        // Floor — tagged so the bounce system can apply the extra upward kick.
220	        var floor = CreateWall(new Rectangle(
221	            -(int)(BoundaryHalfWidth + WallThickness),
222	            (int)BoundaryHalfHeight,
223	            (int)((BoundaryHalfWidth + WallThickness) * 2),
224	            (int)WallThickness), redAndBlue);
225	        floor.Set<FloorTag>();
226	
227	        // Ceiling
228	        CreateWall(new Rectangle(
229	            -(int)(BoundaryHalfWidth + WallThickness),
230	            -(int)(BoundaryHalfHeight + WallThickness),
231	            (int)((BoundaryHalfWidth + WallThickness) * 2),
232	            (int)WallThickness), redAndBlue);
233	
234	        // Left wall
235	        CreateWall(new Rectangle(
236	            -(int)(BoundaryHalfWidth + WallThickness),
237	            -(int)BoundaryHalfHeight,
238	            (int)WallThickness,
239	            (int)BoundaryHalfHeight * 2), redAndBlue);
240	
241	        // Right wall
242	        CreateWall(new Rectangle(
243	            (int)BoundaryHalfWidth,
244	            -(int)BoundaryHalfHeight,
245	            (int)WallThickness,
246	            (int)BoundaryHalfHeight * 2), redAndBlue);
247	    }
248	
249	    private Entity CreateWall(Rectangle bounds, HashSet<int> activeLayers)
250	    {
251	        var wall = _world.CreateEntity();
252	        wall.Set(new TransformComponent(Vector2.Zero));
253	        wall.Set(new BoxColliderComponent(bounds, activeLayers));
254	        return wall;
255	    }
