257	    private void SpawnBalls()
258	    {
259	        for (var i = 0; i < BallSpecs.Length; i++)
260	        {
261	            var spec = BallSpecs[i];
262	            _balls.Add(CreateBall(spec));
263	        }
264	    }
265	
266	    private Entity CreateBall(BallSpec spec)
267	    {
268	        var entity = _world.CreateEntity();
269	        entity.Set(new TransformComponent(spec.Spawn));
270	        entity.Set(new VelocityComponent(spec.Velocity));
271	        entity.Set(new RigidBodyComponent(mass: 1f));
272	        entity.Set(new BallTagComponent { Type = spec.Type });
273	
274	        // Octagonal convex collider as a circle approximation. SAT handles
275	        // polygon-polygon collisions natively, so ball↔ball bounces look round
276	        // rather than square.
277	        var layer = spec.Type == BallType.Red ? RedBallLayer : BlueBallLayer;
278	        entity.Set(new ConvexColliderComponent(
279	            CircleVertices(spec.Radius, segments: 8),
280	            activeLayers: new HashSet<int> { layer }));
281	
282	        var color = spec.Type == BallType.Red ? SproutPalette.Crimson : SproutPalette.SkyBlue;
283	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.95f };
284	        draw.SetMeshData(new CircleMeshGenerator(Vector2.Zero, spec.Radius, color, segments: 24));
285	        entity.Set(draw);
286	        entity.Set<VisibleComponent>();
287	        return entity;
288	    }
289	
290	    private static Vector2[] CircleVertices(float radius, int segments)
291	    {
292	        var verts = new Vector2[segments];
293	        for (var i = 0; i < segments; i++)
294	        {
295	            var a = MathF.PI * 2f * i / segments;
296	            verts[i] = new Vector2(MathF.Cos(a) * radius, MathF.Sin(a) * radius);
297	        }
298	        return verts;
299	    }
