400	    /// Adapter to the `CreateCollisionMessageDelegate<CollisionMessage>` shape that
401	    /// `TransformCollisionDetectionSystem` expects. Always emits Physics-type messages.
402	    private static CollisionMessage CreateCollisionMessage(
403	        Entity entity, Entity target,
404	        Vector2 contactPoint, Vector2 contactNormal,
405	        float contactTime, float penetrationDepth, int layer)
406	        => new(entity, target, contactPoint, contactNormal, contactTime, penetrationDepth, layer, CollisionType.Physics);
407	
408	    private SequentialSystem<GameState> CreateUpdateSystem()
409	    {
410	        // Reference physics pipeline order (per docs/CORE_TENETS.md §5):
411	        //   Movement → Velocity → Detection → Resolution → Commit
412	        // Movement here is gravity-only; ball↔ball/ball↔wall bouncing is the
413	        // custom resolution stage that subscribes to CollisionMessage.
414	        return new SequentialSystem<GameState>(
415	            new CursorInputSystem(_world),
416	            new IntrinsicSizingSystem(_world),
417	            new AutoLayoutSystem(_world, _viewportManager),
418	            new DemoButtonInteractionSystem(_world),
419	            new DemoIconRecolorSystem(_world),
420	            new ToggleSwitchSystem(_world),
421	            new PhysicsDemoInputSystem(this),
422	            new GatedGravitySystem(_world, _runner, this),
423	            new GatedVelocitySystem(_world, _runner, this),
424	            new TransformCollisionDetectionSystem<CollisionMessage>(_world, CreateCollisionMessage),
425	            new BallBounceSystem(_world, this),
426	            new TransformCommitSystem(_world, _runner),
427	            new HierarchySystem(_world),
428	            new CursorPositionSystem(_world, _camera, _viewportManager),
429	            new CursorDrawPrepSystem(_world));
430	    }
431	
432	    private SequentialSystem<GameState> CreateDrawSystem()
433	    {
434	        return new SequentialSystem<GameState>(
435	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering: false),
436	            new TextPrepSystem(_world, pixelPerfectRendering: false),
437	            new MeshPrepSystem(_world),
438	            new ButtonMeshPrepSystem(_world),
439	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
440	                RenderTargetID.Main, _renderTargets[RenderTargetID.Main], _camera),
441	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
442	                RenderTargetID.UI, _renderTargets[RenderTargetID.UI]),
443	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
444	                RenderTargetID.HUD, _renderTargets[RenderTargetID.HUD]),
445	            new FinalDrawSystem(_spriteBatch, _graphicsDevice, _viewportManager, new[]
446	            {
447	                RenderLayer.Main(_renderTargets[RenderTargetID.Main]),
448	                RenderLayer.UI(_renderTargets[RenderTargetID.UI]),
449	                RenderLayer.HUD(_renderTargets[RenderTargetID.HUD]),
450	            }));
451	    }
