453	    public void Dispose()
454	    {
455	        UpdateSystem.Dispose();
456	        DrawSystem.Dispose();
457	        foreach (var rt in _renderTargets.Values) rt.Dispose();
458	        _world.Dispose();
459	        GC.SuppressFinalize(this);
460	    }
