487	/// Edge-triggered keyboard shortcuts for the physics demo.
488	public class PhysicsDemoInputSystem : ISystem<GameState>
489	{
490	    private readonly PhysicsDemoScreen _screen;
491	    private KeyboardState _previous;
492	    public bool IsEnabled { get; set; } = true;
493	
494	    public PhysicsDemoInputSystem(PhysicsDemoScreen screen)
495	    {
496	        _screen = screen;
497	        _previous = Keyboard.GetState();
498	    }
499	
500	    public void Update(GameState state)
501	    {
502	        if (!IsEnabled) return;
503	        var current = Keyboard.GetState();
504	        bool Pressed(Keys k) => current.IsKeyDown(k) && !_previous.IsKeyDown(k);
505	
506	        if (Pressed(Keys.R)) _screen.Reset();
507	        if (Pressed(Keys.Space)) _screen.TogglePause();
508	        if (Pressed(Keys.G)) _screen.ToggleGravity();
509	        if (Pressed(Keys.F)) _screen.ToggleFloorBoost();
510	        if (Pressed(Keys.Escape)) _screen.GoBackToLauncher();
511	
512	        _previous = current;
513	    }
514	
515	    public void Dispose() => GC.SuppressFinalize(this);
516	}
