520	/// Wraps the engine's GravitySystem so it can be paused or toggled off by the
521	/// demo without re-registering the system on toggle.
522	public class GatedGravitySystem : ISystem<GameState>
523	{
524	    private readonly GravitySystem _inner;
525	    private readonly PhysicsDemoScreen _screen;
526	    public bool IsEnabled { get; set; } = true;
527	
528	    public GatedGravitySystem(World world, IParallelRunner runner, PhysicsDemoScreen screen)
529	    {
530	        _screen = screen;
531	        // 1400 max-fall cap matches PhysicsDemoScreen.MaxFallSpeed to prevent
532	        // tunneling at high velocity.
533	        _inner = new GravitySystem(world, runner, worldGravity: 1200f, maxFallVelocity: 1400f);
534	    }
535	
536	    public void Update(GameState state)
537	    {
538	        if (!IsEnabled || !_screen.GravityEnabled) return;
539	        _inner.Update(state);
540	    }
541	
542	    public void Dispose()
543	    {
544	        _inner.Dispose();
545	        GC.SuppressFinalize(this);
546	    }
547	}
