577	
578	/// Custom resolution: subscribes to <see cref="CollisionMessage"/>, pushes the
579	/// base entity out by the MTV, then reflects its velocity along the contact
580	/// normal (with restitution). A floor-tagged collider adds an extra upward
581	/// impulse so the system stays in motion.
582	///
583	/// Replaces the engine's <see cref="TransformCollisionResolutionSystem{T}"/>
584	/// for this demo — that system zeros velocity along the normal (kinematic
585	/// "stop"), which would defeat the bouncing behaviour we want here.
586	public class BallBounceSystem : ISystem<GameState>
587	{
588	    private const float Restitution = 0.85f;
589	    private const float FloorBoost = 260f;
590	
591	    private readonly World _world;
592	    private readonly PhysicsDemoScreen _screen;
593	    private readonly List<CollisionMessage> _collisions = new();
594	
595	    public bool IsEnabled { get; set; } = true;
596	
597	    public BallBounceSystem(World world, PhysicsDemoScreen screen)
598	    {
599	        _world = world;
600	        _screen = screen;
601	        world.Subscribe<CollisionMessage>(OnCollision);
602	    }
603	
604	    private void OnCollision(in CollisionMessage msg) => _collisions.Add(msg);
605	
606	    public void Update(GameState state)
607	    {
608	        if (!IsEnabled)
609	        {
610	            _collisions.Clear();
611	            return;
612	        }
613	
614	        foreach (var msg in _collisions)
615	        {
616	            Resolve(msg);
617	        }
618	        _collisions.Clear();
619	    }
620	
621	    private void Resolve(CollisionMessage msg)
622	    {
623	        var entity = msg.BaseEntity;
624	        var other  = msg.CollidingEntity;
625	        if (!entity.IsAlive || !other.IsAlive) return;
626	
627	        // Walls have no velocity component (and shouldn't move); guard.
628	        if (!entity.Has<VelocityComponent>() || !entity.Has<TransformComponent>()) return;
629	
630	        // Filter blue↔blue: blue balls only collide with walls. They share a
631	        // layer (BlueBallLayer), so the detection system emits the message; we
632	        // discard it here. (Red↔blue is already filtered by layer mismatch.)
633	        if (entity.Has<BallTagComponent>() && other.Has<BallTagComponent>())
634	        {
635	            var a = entity.Get<BallTagComponent>().Type;
636	            var b = other.Get<BallTagComponent>().Type;
637	            if (a == BallType.Blue && b == BallType.Blue) return;
638	        }
639	
640	        ref var transform = ref entity.Get<TransformComponent>();
641	        ref var velocity = ref entity.Get<VelocityComponent>();
642	
643	        var normal = msg.ContactNormal;
644	        if (normal == Vector2.Zero) return;
645	        var penetration = msg.PenetrationDepth;
646	
647	        // SAT normal points from A's center toward B's center, i.e. "into the
648	        // collision" from A's perspective. Push A out along -normal.
649	        // For ball↔ball we apply half-push because the symmetric message
650	        // (A=B, B=A) will arrive too and push the other half; for ball↔wall
651	        // the wall is static and the swept self-skip ensures it never iterates
652	        // as A, so a single full push is correct here.
653	        var isBallVsBall = entity.Has<BallTagComponent>() && other.Has<BallTagComponent>();
654	        var pushScale = isBallVsBall ? 0.5f : 1f;
655	        transform.Translate(-normal * penetration * pushScale);
656	
657	        // Reflect velocity along the contact normal with restitution. Only do
658	        // it if velocity is moving INTO the collision (dot > 0); otherwise the
659	        // ball is already separating and we'd accidentally accelerate it.
660	        var vDotN = Vector2.Dot(velocity.Current, normal);
661	        if (vDotN > 0)
662	        {
663	            velocity.Current -= (1f + Restitution) * vDotN * normal;
664	        }
665	
666	        // Floor kick: extra upward impulse on top of the elastic bounce.
667	        if (_screen.FloorBoostEnabled && other.Has<FloorTag>())
668	        {
669	            // Subtract because Y-down: upward is -Y.
670	            velocity.Current.Y -= FloorBoost;
671	        }
672	    }
673	
674	    public void Dispose()
675	    {
676	        _collisions.Clear();
677	        GC.SuppressFinalize(this);
678	    }
679	}
680

