1	using System;
2	using System.Collections.Generic;
3	using Microsoft.Xna.Framework;
4	using Microsoft.Xna.Framework.Graphics;
5	
6	namespace MonoDreams.Draw;
7	
8	/// <summary>
9	/// Interface for procedural mesh generation. Implementations create vertex/index data
10	/// for various shapes without coupling to game-specific logic.
11	/// </summary>
12	public interface IMeshGenerator
13	{
14	    MeshData Generate();
15	}
16	
17	/// <summary>
18	/// Generates a filled circle mesh using triangle fan pattern.
19	/// </summary>
20	public class CircleMeshGenerator : IMeshGenerator
21	{
22	    public Vector2 Center { get; set; }
23	    public float Radius { get; set; }
24	    public Color Color { get; set; }
25	    public int Segments { get; set; } = 16;
26	
27	    public CircleMeshGenerator(Vector2 center, float radius, Color color, int segments = 16)
28	    {
29	        Center = center;
30	        Radius = radius;
31	        Color = color;
32	        Segments = segments;
33	    }
34	
35	    public MeshData Generate()
36	    {
37	        var vertices = new List<VertexPositionColor>();
38	        var indices = new List<int>();
39	        int indexOffset = 0;
40	
41	        AddCircle(vertices, indices, Center, Radius, Color, ref indexOffset, Segments);
42	
43	        return new MeshData(vertices.ToArray(), indices.ToArray());
44	    }
45	
46	    public static void AddCircle(
47	        List<VertexPositionColor> vertices,
48	        List<int> indices,
49	        Vector2 center,
50	        float radius,
51	        Color color,
52	        ref int indexOffset,
53	        int segments = 16)
54	    {
55	        // Add center vertex
56	        vertices.Add(new VertexPositionColor(new Vector3(center, 0), color));
57	        int centerIndex = indexOffset++;
58	
59	        for (int i = 0; i < segments; i++)
60	        {
61	            float angle1 = 2 * MathF.PI * i / segments;
62	            float angle2 = 2 * MathF.PI * ((i + 1) % segments) / segments;
63	
64	            var point1 = new Vector2(
65	                center.X + radius * MathF.Cos(angle1),
66	                center.Y + radius * MathF.Sin(angle1));
67	
68	            var point2 = new Vector2(
69	                center.X + radius * MathF.Cos(angle2),
70	                center.Y + radius * MathF.Sin(angle2));
71	
72	            vertices.Add(new VertexPositionColor(new Vector3(point1, 0), color));
73	            vertices.Add(new VertexPositionColor(new Vector3(point2, 0), color));
74	
75	            indices.Add(centerIndex);
76	            indices.Add(indexOffset);
77	            indices.Add(indexOffset + 1);
78	
79	            indexOffset += 2;
80	        }
81	    }
82	}
83	
84	/// <summary>
85	/// Generates a line mesh with configurable thickness.
86	/// </summary>
87	public class LineMeshGenerator : IMeshGenerator
88	{
89	    public Vector2 Start { get; set; }
90	    public Vector2 End { get; set; }
91	    public float Thickness { get; set; }
92	    public Color Color { get; set; }
93	
94	    public LineMeshGenerator(Vector2 start, Vector2 end, float thickness, Color color)
95	    {
96	        Start = start;
97	        End = end;
98	        Thickness = thickness;
99	        Color = color;
100	    }
101	
102	    public MeshData Generate()
103	    {
104	        var vertices = new List<VertexPositionColor>();
105	        var indices = new List<int>();
106	        int indexOffset = 0;
107	
108	        AddLine(vertices, indices, Start, End, Thickness, Color, ref indexOffset);
109	
110	        return new MeshData(vertices.ToArray(), indices.ToArray());
111	    }
112	
113	    public static void AddLine(
114	        List<VertexPositionColor> vertices,
115	        List<int> indices,
116	        Vector2 start,
117	        Vector2 end,
118	        float thickness,
119	        Color color,
120	        ref int indexOffset)
121	    {
122	        Vector2 direction = end - start;
123	        Vector2 perpendicular = new(-direction.Y, direction.X);
124	        perpendicular.Normalize();
125	        perpendicular *= thickness / 2;
126	
127	        vertices.Add(new VertexPositionColor(new Vector3(start + perpendicular, 0), color));
128	        vertices.Add(new VertexPositionColor(new Vector3(start - perpendicular, 0), color));
129	        vertices.Add(new VertexPositionColor(new Vector3(end - perpendicular, 0), color));
130	        vertices.Add(new VertexPositionColor(new Vector3(end + perpendicular, 0), color));
131	
132	        indices.Add(indexOffset);
133	        indices.Add(indexOffset + 1);
134	        indices.Add(indexOffset + 2);
135	
136	        indices.Add(indexOffset);
137	        indices.Add(indexOffset + 2);
138	        indices.Add(indexOffset + 3);
139	
140	        indexOffset += 4;
141	    }
142	}
143	
144	/// <summary>
145	/// Generates a rectangle outline mesh with configurable thickness.
146	/// </summary>
147	public class RectangleOutlineMeshGenerator : IMeshGenerator
148	{
149	    public Rectangle Bounds { get; set; }
150	    public float Thickness { get; set; }
151	    public Color Color { get; set; }
152	
153	    public RectangleOutlineMeshGenerator(Rectangle bounds, float thickness, Color color)
154	    {
155	        Bounds = bounds;
156	        Thickness = thickness;
157	        Color = color;
158	    }
159	
160	    public MeshData Generate()
161	    {
162	        var vertices = new List<VertexPositionColor>();
163	        var indices = new List<int>();
164	        int indexOffset = 0;
165	
166	        var topLeft = new Vector2(Bounds.Left, Bounds.Top);
167	        var topRight = new Vector2(Bounds.Right, Bounds.Top);
168	        var bottomRight = new Vector2(Bounds.Right, Bounds.Bottom);
169	        var bottomLeft = new Vector2(Bounds.Left, Bounds.Bottom);
170	
171	        // Top edge
172	        LineMeshGenerator.AddLine(vertices, indices, topLeft, topRight, Thickness, Color, ref indexOffset);
173	        // Right edge
174	        LineMeshGenerator.AddLine(vertices, indices, topRight, bottomRight, Thickness, Color, ref indexOffset);
175	        // Bottom edge
176	        LineMeshGenerator.AddLine(vertices, indices, bottomRight, bottomLeft, Thickness, Color, ref indexOffset);
177	        // Left edge
178	        LineMeshGenerator.AddLine(vertices, indices, bottomLeft, topLeft, Thickness, Color, ref indexOffset);
179	
180	        return new MeshData(vertices.ToArray(), indices.ToArray());
181	    }
182	}
183	
184	/// <summary>
185	/// Generates a dashed rectangle outline. Each edge is broken into evenly spaced
186	/// dashes of <see cref="DashLength"/> separated by gaps of <see cref="GapLength"/>,
187	/// drawn with <see cref="Thickness"/> using <see cref="LineMeshGenerator"/> segments.
188	/// Dash spacing is fitted per-edge so every edge begins and ends on a dash — no
189	/// half-dash bleeds past a corner.
190	/// </summary>
191	public class DashedRectangleOutlineMeshGenerator : IMeshGenerator
192	{
193	    public Rectangle Bounds { get; set; }
194	    public float Thickness { get; set; }
195	    public Color Color { get; set; }
196	    public float DashLength { get; set; }
197	    public float GapLength { get; set; }
198	
199	    public DashedRectangleOutlineMeshGenerator(
200	        Rectangle bounds, float thickness, Color color, float dashLength = 12f, float gapLength = 8f)
201	    {
202	        Bounds = bounds;
203	        Thickness = thickness;
204	        Color = color;
205	        DashLength = dashLength;
206	        GapLength = gapLength;
207	    }
208	
209	    public MeshData Generate()
210	    {
211	        var vertices = new List<VertexPositionColor>();
212	        var indices = new List<int>();
213	        int indexOffset = 0;
214	
215	        var topLeft = new Vector2(Bounds.Left, Bounds.Top);
216	        var topRight = new Vector2(Bounds.Right, Bounds.Top);
217	        var bottomRight = new Vector2(Bounds.Right, Bounds.Bottom);
218	        var bottomLeft = new Vector2(Bounds.Left, Bounds.Bottom);
219	
220	        AddDashedEdge(vertices, indices, topLeft, topRight, ref indexOffset);
221	        AddDashedEdge(vertices, indices, topRight, bottomRight, ref indexOffset);
222	        AddDashedEdge(vertices, indices, bottomRight, bottomLeft, ref indexOffset);
223	        AddDashedEdge(vertices, indices, bottomLeft, topLeft, ref indexOffset);
224	
225	        return new MeshData(vertices.ToArray(), indices.ToArray());
226	    }
227	
228	    private void AddDashedEdge(
229	        List<VertexPositionColor> vertices, List<int> indices,
230	        Vector2 start, Vector2 end, ref int indexOffset)
231	    {
232	        float length = Vector2.Distance(start, end);
233	        if (length <= 0f) return;
234	        Vector2 dir = (end - start) / length;
235	
236	        // An edge too short for a single dash just gets one solid segment.
237	        if (length <= DashLength)
238	        {
239	            LineMeshGenerator.AddLine(vertices, indices, start, end, Thickness, Color, ref indexOffset);
240	            return;
241	        }
242	
243	        // Fit a whole number of dash+gap periods so the final dash lands exactly on
244	        // the corner. periods+1 dashes are drawn; the last starts at (length - DashLength).
245	        float period = DashLength + GapLength;
246	        int periods = Math.Max(1, (int)MathF.Round((length - DashLength) / period));
247	        float spacing = (length - DashLength) / periods;
248	
249	        for (int i = 0; i <= periods; i++)
250	        {
251	            float dashStart = i * spacing;
252	            float dashEnd = Math.Min(dashStart + DashLength, length);
253	            LineMeshGenerator.AddLine(
254	                vertices, indices, start + dir * dashStart, start + dir * dashEnd, Thickness, Color, ref indexOffset);
255	        }
256	    }
257	}
258	
259	/// <summary>
260	/// Generates a filled rectangle mesh.
261	/// </summary>
262	public class FilledRectangleMeshGenerator : IMeshGenerator
263	{
264	    public Rectangle Bounds { get; set; }
265	    public Color Color { get; set; }
266	
267	    public FilledRectangleMeshGenerator(Rectangle bounds, Color color)
268	    {
269	        Bounds = bounds;
270	        Color = color;
271	    }
272	
273	    public MeshData Generate()
274	    {
275	        var vertices = new VertexPositionColor[]
276	        {
277	            new(new Vector3(Bounds.Left, Bounds.Top, 0), Color),
278	            new(new Vector3(Bounds.Right, Bounds.Top, 0), Color),
279	            new(new Vector3(Bounds.Right, Bounds.Bottom, 0), Color),
280	            new(new Vector3(Bounds.Left, Bounds.Bottom, 0), Color)
281	        };
282	
283	        var indices = new int[] { 0, 1, 2, 0, 2, 3 };
284	
285	        return new MeshData(vertices, indices);
286	    }
287	}
288	
289	/// <summary>
290	/// Generates a gradient mesh along a path with configurable width and color function.
291	/// </summary>
292	public class GradientPathMeshGenerator : IMeshGenerator
293	{
294	    public Vector2[] PathPoints { get; set; }
295	    public float Width { get; set; }
296	    public Func<float, Color> ColorFunction { get; set; }
297	
298	    public GradientPathMeshGenerator(Vector2[] pathPoints, float width, Func<float, Color> colorFunction)
299	    {
300	        PathPoints = pathPoints;
301	        Width = width;
302	        ColorFunction = colorFunction;
303	    }
304	
305	    public MeshData Generate()
306	    {
307	        if (PathPoints == null || PathPoints.Length < 2)
308	            return new MeshData();
309	
310	        var vertices = new List<VertexPositionColor>();
311	        var indices = new List<int>();
312	
313	        for (int i = 0; i < PathPoints.Length; i++)
314	        {
315	            float t = (float)i / (PathPoints.Length - 1);
316	            var color = ColorFunction(t);
317	
318	            // Calculate perpendicular for width
319	            Vector2 direction;
320	            if (i == 0)
321	                direction = PathPoints[1] - PathPoints[0];
322	            else if (i == PathPoints.Length - 1)
323	                direction = PathPoints[i] - PathPoints[i - 1];
324	            else
325	                direction = PathPoints[i + 1] - PathPoints[i - 1];
326	
327	            direction.Normalize();
328	            var perpendicular = new Vector2(-direction.Y, direction.X) * (Width / 2);
329	
330	            vertices.Add(new VertexPositionColor(
331	                new Vector3(PathPoints[i] + perpendicular, 0), color));
332	            vertices.Add(new VertexPositionColor(
333	                new Vector3(PathPoints[i] - perpendicular, 0), color));
334	
335	            if (i > 0)
336	            {
337	                int baseIndex = (i - 1) * 2;
338	                indices.Add(baseIndex);
339	                indices.Add(baseIndex + 1);
340	                indices.Add(baseIndex + 2);
341	
342	                indices.Add(baseIndex + 1);
343	                indices.Add(baseIndex + 3);
344	                indices.Add(baseIndex + 2);
345	            }
346	        }
347	
348	        return new MeshData(vertices.ToArray(), indices.ToArray());
349	    }
350	}
351	
352	/// <summary>
353	/// Combines multiple mesh generators into a single mesh.
354	/// </summary>
355	public class CompositeMeshGenerator : IMeshGenerator
356	{
357	    private readonly List<IMeshGenerator> _generators = new();
358	
359	    public CompositeMeshGenerator Add(IMeshGenerator generator)
360	    {
361	        _generators.Add(generator);
362	        return this;
363	    }
364	
365	    public MeshData Generate()
366	    {
367	        var allVertices = new List<VertexPositionColor>();
368	        var allIndices = new List<int>();
369	
370	        foreach (var generator in _generators)
371	        {
372	            var mesh = generator.Generate();
373	            int indexOffset = allVertices.Count;
374	
375	            allVertices.AddRange(mesh.Vertices);
376	            foreach (var index in mesh.Indices)
377	            {
378	                allIndices.Add(index + indexOffset);
379	            }
380	        }
381	
382	        return new MeshData(allVertices.ToArray(), allIndices.ToArray());
383	    }
384	}
