import glob, os
try:
    from PIL import Image
except ImportError:
    print("NO_PIL"); raise SystemExit
# flash targets
targets = {
    "red_flash":  (255, 90, 80),
    "blue_flash": (150,230,255),
    "floor_flash":(190,255,150),
    "floor_green":(106,190,89),
}
def close(c, t, tol=22):
    return all(abs(c[i]-t[i])<=tol for i in range(3))
files = sorted(glob.glob("*.png"))
for f in files:
    im = Image.open(f).convert("RGB")
    px = im.load()
    w,h = im.size
    found = {k:0 for k in targets}
    # sample every 3rd pixel for speed
    for y in range(0,h,3):
        for x in range(0,w,3):
            c = px[x,y]
            for k,t in targets.items():
                if close(c,t):
                    found[k]+=1
    hits = {k:v for k,v in found.items() if v>3}
    if hits:
        n = f.split("_")[1]
        print(n, hits)
