215	public static partial class DemoUIRowExtensions
216	{
217	    /// Composite "key cap + label" row used by sidebar menus. The cap shows
218	    /// a small letter or digit on a sprite background; the row label is the
219	    /// human-readable command name. The whole row is one clickable hit-box.
220	    public static (Entity Container, Entity Outline, Vector2 Size) CreateKeyRow(
221	        this World world,
222	        string id,
