/// Visual feedback (FlashComponent + FlashSystem): a ball blinks a vivid color on
/// every impact. The floor is a thick line — cream when the boost is off, green
/// when on — and blinks bright green when a ball lands on it while the boost is on.
public class PhysicsDemoScreen : IGameScreen
{
    private const float BoundaryHalfWidth  = 380f;
    private const float BoundaryHalfHeight = 220f;
    private const float WallThickness      = 20f;

    private const float Gravity      = 1200f;    // px/s²
    private const float Restitution  = 0.85f;    // wall/ball bounce energy retention
    private const float FloorBoost   = 260f;     // extra upward px/s on floor contact
    private const float MaxFallSpeed = 1400f;    // safety cap to prevent tunneling

    private const float FloorVisualThickness = 6f;     // thick floor line vs the 2px boundary
    private const float FlashDuration        = 0.25f;  // seconds for a blink to fade back

    private const float MinSpawnSpeed = 120f;    // random initial-velocity speed range
    private const float MaxSpawnSpeed = 220f;

    /// Floor line tints: regular (boost off), green (boost on), bright blink on a boosted hit.
    private static readonly Color FloorRegularColor = SproutPalette.TextLight;
    private static readonly Color FloorActiveColor  = new(106, 190, 89);
    private static readonly Color FloorFlashColor   = new(190, 255, 150);

    private const int RedBallLayer  = 0;
    private const int BlueBallLayer = 1;
    // Walls own both layers so red and blue both collide with them.

    /// 10 balls: 7 red (Type=Red) collide with walls + reds; 3 blue (Type=Blue)
    /// collide with walls only. Sizes mostly small with a couple of larger reds
    /// for visual variety. Initial velocities are randomized per spawn/reset
    /// (random direction + speed), so only spawn position and size are fixed here.
    private static readonly BallSpec[] BallSpecs =
    {
        new(BallType.Red,   radius: 10f, spawn: new Vector2(-300, -160)),
        new(BallType.Red,   radius: 14f, spawn: new Vector2(-150, -160)),
        new(BallType.Red,   radius: 10f, spawn: new Vector2(   0, -160)),
        new(BallType.Red,   radius: 18f, spawn: new Vector2( 150, -160)),
        new(BallType.Red,   radius: 11f, spawn: new Vector2( 300, -160)),
        new(BallType.Red,   radius: 12f, spawn: new Vector2(-220,  -80)),
        new(BallType.Red,   radius: 22f, spawn: new Vector2( 220,  -80)),
        new(BallType.Blue,  radius: 13f, spawn: new Vector2( -80,  -80)),
        new(BallType.Blue,  radius: 20f, spawn: new Vector2(  80,  -80)),
        new(BallType.Blue,  radius: 15f, spawn: new Vector2(   0,    0)),
    };

    private readonly ContentManager _content;
    private readonly GraphicsDevice _graphicsDevice;
    private readonly MonoDreams.Component.Camera _camera;
    private readonly ViewportManager _viewportManager;
    private readonly SpriteBatch _spriteBatch;
    private readonly IParallelRunner _runner;
    private readonly World _world;
    private readonly Dictionary<RenderTargetID, RenderTarget2D> _renderTargets;

