private Entity CreateWall(Rectangle bounds, HashSet<int> activeLayers)
{
    var wall = _world.CreateEntity();
    wall.Set(new TransformComponent(Vector2.Zero));
    wall.Set(new BoxColliderComponent(bounds, activeLayers));
